INSERT INTO meili_dashboard.mentions VALUES ('6e7c6021-fc7c-4b1c-b2a7-2a25aa591cad', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'facebook', 'post', 'pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl', '', 'search', 'Meili Mi Bo Dai Loan', 'Meili Mi Bo Dai Loan', 'https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl', 'Meili 美丽 - Mì Bò Đài Loan, Thành phố Hồ Chí Minh. 2.270 lượt thích · 157 người đang nói về điều này · 103 lượt đăng ký ở đây. Meili thương mời mì bò Đài...', NULL, '2026-05-18 10:33:00.14485+07', DEFAULT, true, true, '{}', NULL, '{"source": "facebook_keyword_filter_job", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "comments": [{"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_1", "text": "Meili 美丽 - Mì Bò Đài Loan", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195488+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_1", "record_type": "comment", "keyword_match": true, "keyword_matches": ["Mì Bò Đài Loan"], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_2", "text": "Mấy lần trước ăn ok , 2vc mới quay lại ăn xong vài phút trc, mà nay nước lèo của quán bị chua, có gọi nhân viên ra nói nhỏ mà sao thấy mấy bạn lơ lơ ko nói gì, mấy bạn mang chén nước lèo vô xong cũng ko đổi mang chén khác ra cho mình ... nay có trải nghiệm hơi thất vọng, vì vợ mình cũng chịu quán này lắm. Góp ý tích cực mong quán cải thiện nha. Meili 美丽 - Mì Bò Đài Loan", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195497+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_2", "record_type": "comment", "keyword_match": true, "keyword_matches": ["Mì Bò Đài Loan"], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_3", "text": "nước lèo thì ăn chứ nươc dùng thì không", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195502+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_3", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_4", "text": "Mì bò thì ok. Chân gà tàu xì thì khá tệ, vừa dai, vừa lạt nhách, chả có vị gì. Xíu mại thì mình cảm giác là xíu mại gói của bamboo. Quán kê bàn ghế khá sát nên hơi chật, với cũng khá nóng. Ăn mà để xe ngoài tầm mắt ko có nhân viên trông có cảm giác hơi bất an.", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-