INSERT INTO meili_dashboard.mentions VALUES ('f19e32e7-c235-42a5-86a8-78f2f23dd00a', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'tiktok', 'post', '7515774008558685447', '', '6642144675481747457', 'doquan722', 'doquan722', 'https://www.tiktok.com/@doquan722/video/7515774008558685447', 'Ý là cũng rảnh nên bày vẽ tí 🤣🤣 Phần 154: Mì bò Đài Loan  Cách làm: - nạm bò thái miếng ( khoảng 300g), ướp cùng 1 thìa cf đường, 1 thìa cf mì chính, 1 xíu muối, 1 thìa xì dầu, 2 thìa hắc xì dầu ( xì dầu đặc biệt), 1 xíu dầu ăn, ướp khoảng 15p - cho hoa hồi, quế, ớt khô vào đảo thơm rồi cho thịt bò, gừng, hành tây vào xào thơm - cho nước lọc, 1 thìa tương đậu bản ( không có thì bỏ qua) thêm cà rốt, củ cải trắng, táo vào ninh cho thịt mềm, nêm nếm lại cho vừa ăn - mì tươi: cho khoảng 1/2 bát con bột mì trộn với 1 quả trứng gà, 1 xíu muối cho sợi mì đậm đà hơn. - Nhồi thành khối rồi bọc kín, ủ khoảng 15p rồi đem ra cán mỏng, thái sợi - cho mì vào luộc từ 5-7 phút, ăn thử mì không bị bột nữa là chín - cho mì vào bát, thêm thịt bò, cà rốt và các loại topping như trứng luộc, cải chua, cải luộc… - chan nước dùng, rắc thêm hành lá là xong. Chúc cả nhà ngon miệng 🤣🤣 #Quancooking #ĐỗQuân #vtvcab #tiktokfood #LearnOnTikTok #asmrfood #xuhuong #viral #mi #mibo #mibodailoan #taiwanfood', NULL, '2025-06-14 19:01:44+07', DEFAULT, true, true, '{"digg_count": 29200, "play_count": 681000, "share_count": 2101, "comment_count": 273}', NULL, '{"stats": {"digg_count": 29200, "play_count": 681000, "share_count": 2101, "comment_count": 273}, "source": "tiktok_keyword_filter_job", "page_id": "6642144675481747457", "post_id": "7515774008558685447", "comments": [{"url": "https://www.tiktok.com/@doquan722/video/7515774008558685447?comment_id=comment-level-1", "text": "tương đậu bản là gì ak", "author": "", "post_id": "7515774008558685447", "created_at": "2026-05-15T08:44:02.053175+00:00", "external_id": "comment:comment-level-1", "record_type": "comment", "crawl_source": "dom", "keyword_match":