INSERT INTO meili_dashboard.raw_documents VALUES ('7c982d7b-f74c-42c6-b336-ac5b9fdf8c27', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'facebook', 'mention_post', 'facebook:post:1554723448837394', 'https://www.facebook.com/photo/?fbid=1554723448837394&set=pcb.1985367128879042', '2026-05-18 10:31:38.865496+07', '{"source": "facebook_keyword_filter_job", "page_id": "search", "post_id": "1554723448837394", "comments": [], "platform": "facebook", "post_url": "https://www.facebook.com/photo/?fbid=1554723448837394&set=pcb.1985367128879042", "page_name": "Meili Mì Bò Đài Loan", "post_text": "Mì bò Đài Loan tô 39k mà thịt bò nhiều cỡ này là có lời ko ta ??? \n\nThiệt là siêu ấn tượng với mì bò ở đây, nhiều thịt, nước dùng đậm đà thơm xĩu, có cải chua ăn kèm đỡ ngán nữa nha quý dzị\n\n👉 Mì xá xíu sủi cảo khô cũng ngon chấn động, sợi mì dai thịt xá xíu mềm thấm xốt, sủi cảo có nguyên con tôm tươi bên trong\n\nNgoài mì thì ghé đây nhất định phải kêu mấy món Dimsum, vỏ mỏng nhân thịt, tôm, giò chắc nụi. Nước chấm đỉnh cao khó ở đâu đọ lại 🤌🏻\n\nMấy món khác xếp theo thứ tự ngon từ trên xuống là Sủi cảo chiên, Chân gà tàu xì, Pao kẹp gà phô mai 🌟\n\nĐánh giá chung:\n- Không gian: 9/10 (Về chiều tối bật đèn lồng chill)\n- Món ăn: 9/10\n- Giá: 10/10\n- Phục vụ: 10/10\n- Vệ sinh: 9/10\n🔥TỔNG: 47/50\n\n📍Meili Mì Bò Đài Loan - 2B Mai Văn Vĩnh, P.Tân Quy, Quận 7\nCN Gò Vấp: 213 Nguyễn Văn Khối, P8, Gò Vấp\n\n#Mmsg", "source_file": "/Users/khangnhq/Desktop/WorkGalaxy/social-listening/data/facebook/raw/meili_mi_bo_dai_loan/20260518/search_Meili Mì Bò Đài Loan.jsonl", "fnb_relevance": {"branch_hits": [], "negative_hits": [], "positive_hits": ["mì bò", "đài loan", "sủi cảo", "món ăn", "ăn", "đánh giá"], "is_relevant_fnb": true, "relevance_score": 17, "generic_brand_hits": ["meili"], "explicit_brand_hits": ["meili mì bò đài loan", "mì bò đài loan"]}, "post_created_at": "2026-05-18T03:31:38.865496+00:00", "post_keyword_match": true, "parent_keyword_match": true, "post_keywo