INSERT INTO meili_dashboard.raw_documents VALUES ('87930357-45f4-435f-807b-999a5a8f2750', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'facebook', 'mention_post', 'facebook:post:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl', 'https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl', '2026-05-18 10:33:00.14485+07', '{"source": "facebook_keyword_filter_job", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "comments": [{"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_1", "text": "Meili 美丽 - Mì Bò Đài Loan", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195488+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_1", "record_type": "comment", "keyword_match": true, "keyword_matches": ["Mì Bò Đài Loan"], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_2", "text": "Mấy lần trước ăn ok , 2vc mới quay lại ăn xong vài phút trc, mà nay nước lèo của quán bị chua, có gọi nhân viên ra nói nhỏ mà sao thấy mấy bạn lơ lơ ko nói gì, mấy bạn mang chén nước lèo vô xong cũng ko đổi mang chén khác ra cho mình ... nay có trải nghiệm hơi thất vọng, vì vợ mình cũng chịu quán này lắm. Góp ý tích cực mong quán cải thiện nha. Meili 美丽 - Mì Bò Đài Loan", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195497+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_2", "record_type": "comment", "keyword_match": true, "keyword_matches": ["Mì Bò Đài Loan"], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_3", "text": "nước lèo thì ăn chứ nươc dùng thì không", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195502+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_3", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_4", "text": "Mì bò thì ok. Chân gà tàu xì thì khá tệ, vừa dai, vừa lạt nhách, chả có vị gì. Xíu mại thì mình cảm giác là xíu mại gói của bamboo. Quán kê bàn ghế khá sát nên hơi chật, với cũng khá nóng. Ăn mà để xe ngoài tầm mắt ko có nhân viên trông có cảm giác hơi bất an.", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195506+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_4", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_5", "text": "Góp ý nhẹ vị gà chiên nên thay đổi vì ăn gà chiên nhưng vị y chang lạp xưởng", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195510+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_5", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_6", "text": "Thư Nguyễn di ăn nè e", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195515+00:00", "external_id": "comment:pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_6", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl?comment_id=pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl_7", "text": "Tuan Dang nhận lương lẹ lên r đi ăn", "author": "Meili Mi Bo Dai Loan", "page_id": "search", "post_id": "pfbid02cTea213bcAFooCyhcczCbPrP1VMZyriANJQPmUpXGmpssD9rGLQW2Z2xgvYCs5dUl", "page_name": "Meili Mi Bo Dai Loan", "created_at": "2026-05-19T20:01:05.195519+00:00", "external_id": "comment:pfbid02