INSERT INTO meili_dashboard.raw_documents VALUES ('23bd9a30-a0ef-426e-8754-6fb8bd07e76c', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'instagram', 'mention_post', 'instagram:post:DXUGlg-idX7', 'https://www.instagram.com/p/DXUGlg-idX7/', '2026-05-14 23:28:09.122671+07', '{"stats": {"like_count": null, "comment_count": 0}, "source": "instagram_keyword_filter_job", "page_id": "", "post_id": "DXUGlg-idX7", "comments": [{"url": "https://www.instagram.com/p/DXUGlg-idX7/#comment-1", "text": "ủa lẹ v", "author": "mitranngg", "post_id": "DXUGlg-idX7", "created_at": "2026-04-23T16:28:09.122671+00:00", "external_id": "comment:mitranngg|3w|-a-l-v", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "3w", "parent_comment_id": ""}], "platform": "instagram", "post_url": "https://www.instagram.com/p/DXUGlg-idX7/", "page_name": "𝐂𝐡𝐞𝐞𝐬𝐢𝐞’𝐬 𝐋𝐢𝐟𝐞 🛍️✈️🍡", "post_text": "165 likes, 3 comments - eatwithcheesie on April 19, 2026: &quot;YUTANG - TRÀ SỮA VÀ MÓN ĂN ĐÀI LOAN\n⏰10h-22h\n💸Menu ảnh cuối\nYu Tang đang có khuyến mãi giảm 15% tổng bill đến hết 30/4/2026 nè, ai muốn thử mì bò, trà sữa và gà Đài Loan thì tranh thủ ghé nha 🫶🏻\n\n🍜MÌ BẮP BÒ ĐÀI LOAN (95k): Tô mì khá lớn nhưng vừa đủ cho 1 người ăn, sợi mì mềm, nước dùng trong vị thanh vừa miệng, thịt bắp bò mềm có mấy chỗ gân sựt sựt ăn ok nha, miếng thịt được cắt dày mà cũng tầm 4-5 miếng gì đấy ăn đã.\n🥟HÁ CẢO ĐÀI LOAN (65k): Phần há cảo thì mình chọn nhân tôm bầu với sốt xì dầu. Vỏ há cảo hơi dày nhưng vẫn mềm dẻo, phần nhân thì không có gì đặc biệt, phần sốt xì dầu thì nồng mùi giấm hơi chua, món này không hợp khẩu vị mình lắm.\n🍗GÀ RÁN KHỔNG LỒ (99k): Must try khi đến đây nhé, miếng gà lớn bên ngoài lớp bột tẩm chiên giòn rụm với được ướp rồi nên vị đậm đà khỏi chấm ăn vẫn ngon, thịt gà mềm ăn ngon.\n🧋TRÀ SỮA TRÂN CHÂU NGHỆ NHÂN (M-60k): Ban đầu mình khá mong đợi món này nhưng lúc uống thì hơi thất vọng nhẹ, vị trà sữa khá nhạt không cảm nhận rõ được vị lắm, trân châu thì ngọt mềm dẻo ăn khá ngon.\n\nTóm lại là với mình thì món nên thử là gà rán khổng lồ và mì bò, còn lại ai thích gì thì cứ thử xem sao nhé, tranh thủ đang khuyến mãi tới ăn cho biết tại sao hot ^^\n__________\n📍Tầng hầm B - Vạn Hạnh Mall: 11 Sư Vạn Hạnh, Hòa Hưng (Q.10 cũ), HCM\n__________\n🚫LẤY ẢNH VUI LÒNG GHI NGUỒN &amp; KHÔNG XOÁ WATERMARK GIÚP MÌNH. XIN CẢM ƠN!\n#eatwithcheesie#mibodailoan#dimsum#trasua#garan&quot;.", "source_file": "data/instagram/raw/meili_mi_bo_dai_loan/instagram_all_posts.json", "fnb_relevance": {"branch_hits": [], "negative_hits": [], "positive_hits": ["mì bò", "đài loan", "món ăn", "ăn", "menu"], "is_relevant_fnb": true, "relevance_score": 8, "generic_brand_hits": [], "explicit_brand_hits": []}, "post_created_at": "2026-05-14T16:28:09.122671+00:00", "post_keyword_match": true, "parent_keyword_match": true, "post_keyword_matches": ["#mibodailoan"]}', '165 likes, 3 comments - eatwithcheesie on April 19, 2026: &quot;YUTANG - TRÀ SỮA VÀ MÓN ĂN ĐÀI LOAN
