INSERT INTO meili_dashboard.raw_documents VALUES ('cd4a6ab1-dd22-46a3-82ab-eaf9a3191b56', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'facebook', 'mention_post', 'facebook:post:pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl', 'https://www.facebook.com/nhami5c/posts/pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl', '2026-05-16 19:46:39.793536+07', '{"source": "facebook_keyword_filter_job", "page_id": "search", "post_id": "pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl", "comments": [{"url": "https://www.facebook.com/nhami5c/posts/pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl?comment_id=pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_1", "text": "Meili 美丽 - Mì Bò Đài Loan", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.179994+00:00", "external_id": "comment:pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_1", "record_type": "comment", "keyword_match": true, "keyword_matches": ["Mì Bò Đài Loan"], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl?comment_id=pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_2", "text": "Mấy lần trước ăn ok , 2vc mới quay lại ăn xong vài phút trc, mà nay nước lèo của quán bị chua, có gọi nhân viên ra nói nhỏ mà sao thấy mấy bạn lơ lơ ko nói gì, mấy bạn mang chén nước lèo vô xong cũng ko đổi mang chén khác ra cho mình ... nay có trải nghiệm hơi thất vọng, vì vợ mình cũng chịu quán này lắm. Góp ý tích cực mong quán cải thiện nha. Meili 美丽 - Mì Bò Đài Loan", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.179997+00:00", "external_id": "comment:pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_2", "record_type": "comment", "keyword_match": true, "keyword_matches": ["Mì Bò Đài Loan"], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl?comment_id=pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_3", "text": "Mì bò thì ok. Chân gà tàu xì thì khá tệ, vừa dai, vừa lạt nhách, chả có vị gì. Xíu mại thì mình cảm giác là xíu mại gói của bamboo. Quán kê bàn ghế khá sát nên hơi chật, với cũng khá nóng. Ăn mà để xe ngoài tầm mắt ko có nhân viên trông có cảm giác hơi bất an.", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.179999+00:00", "external_id": "comment:pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_3", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl?comment_id=pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_4", "text": "nước lèo thì ăn chứ nươc dùng thì không", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.180001+00:00", "external_id": "comment:pfbid02c9r3kVk8c2yDuYBrvt8MDfYDrVhszM2jmPd1CRr5LzoWpfFbySh3Kr955KcncfhSl_4", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "pa