INSERT INTO meili_dashboard.raw_documents VALUES ('7084adb2-121c-472a-98c8-59ca7d6355ee', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'instagram', 'mention_post', 'instagram:post:DVh9cUdj84Q', 'https://www.instagram.com/p/DVh9cUdj84Q/', '2026-05-15 15:04:17.182429+07', '{"stats": {"like_count": null, "comment_count": 0}, "source": "instagram_keyword_filter_job", "page_id": "", "post_id": "DVh9cUdj84Q", "comments": [{"url": "https://www.instagram.com/p/DVh9cUdj84Q/#comment-1", "text": "sốt sa cha này có cay ko bạn? mình hỏi để làm cho bé ăn í", "author": "jennythanh", "post_id": "DVh9cUdj84Q", "created_at": "2026-03-06T08:04:17.182429+00:00", "external_id": "comment:jennythanh|10w|s-t-sa-cha-n-y-c-cay-ko-b-n-m-nh-h-i-l-m-cho-b-n-", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "10w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/DVh9cUdj84Q/#comment-2", "text": "👏👏", "author": "phoronglaval", "post_id": "DVh9cUdj84Q", "created_at": "2026-03-13T08:04:17.182429+00:00", "external_id": "comment:phoronglaval|9w|-", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "9w", "parent_comment_id": ""}], "platform": "instagram", "post_url": "https://www.instagram.com/p/DVh9cUdj84Q/", "page_name": "Huyenchuothomecook", "post_text": "huyenchuothomecook on March 5, 2026: &quot;Ai ăn Mì bò Đài Loan hơm ~~\n\n🌱500gr Nạm bò\n3 muỗng canh Sốt SACHA - Lee Kum Kee\n1 muỗng canh đường\n1 muỗng canh nước tương\n1 muỗng canh tương hột ớt\n\nƯớp bò cùng hỗn hợp trên ít nhất 1 tiếng\n\n🌱Túi gia vị thảo mộc:\n10gr quế\n5 cây đinh hương\n4 trái thảo quả\n15gr tiểu hồi\n5gr đại hồi (5 cái)\n3gr lá thơm\n10gr hạt xuyên tiêu\n\nCho quế, thảo quả, đại hồi, lá thơm vào rang trước\nrồi tiếp đến cho đinh hương, tiểu hồi, xuyên tiêu\n\n(1) Phi thơm Hành lá, tỏi, gừng\n\n(2) Cho bò vào đảo săn lại rồi cho nước vào hầm - thêm túi gia vị vào\n\nNêm chút muối hạt và đường phèn\n\n(3) Nấu đến khi bò mềm thì nêm nếm gia vị lại\n\n(4) Chuẩn bị ít dưa chua ăn kèm:\nPhi thơm tỏi, cho dưa chua vào xào\n\n(5) Cải thìa luộc\n\n(6) Trụng mì, đổ nước hầm vào tô, ăn cùng cải thìa, dưa chua, ớt xắt\n\n#huyenchuothomecook #mibodailoan #homecooking #mibodailoan&quot;.", "source_file": "data/instagram/raw/meili_mi_bo_dai_loan/instagram_all_posts.json", "fnb_relevance": {"branch_hits": [], "negative_hits": [], "positive_hits": ["mì bò", "đài loan", "ăn"], "is_relevant_fnb": true, "relevance_score": 10, "generic_brand_hits": [], "explicit_brand_hits": ["mì bò đài loan"]}, "post_created_at": "2026-05-15T08:04:17.182429+00:00", "post_keyword_match": true, "parent_keyword_match": true, "post_keyword_matches": ["Mì Bò Đài Loan", "#mibodailoan"]}', 'huyenchuothomecook on March 5, 2026: &quot;Ai ăn Mì bò Đài Loan hơm ~~
INSERT INTO meili_dashboard.raw_documents VALUES ('1260dc60-82dc-4c11-b647-33a41de749be', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'instagram', 'mention_post', 'instagram:post:C4P5EqgvHd1', 'https://www.instagram.com/p/C4P5EqgvHd1/', '2026-05-15 15:08:56.700282+07', '{"stats": {"like_count": null, "comment_count": 0}, "source": "instagram_keyword_filter_job", "page_id": "", "post_id": "C4P5EqgvHd1", "comments": [{"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-1", "text": "Đối với khẩu vị cá nhân của mình thì đồ ăn khá nhạt và không có điểm nào quá đặc biệt, người yêu mình thường ăn nhạt hơn mình nhưng bạn ấy cũng có đánh giá tương tự. Mình order thử cả mì bò và mì sủi cảo tại quán và cả 2 món đều có nước dùng kém đậm đà hơn so với vài chỗ có những món tương tự mà mình từng ăn trước đây. Tuy nhiên, đây chỉ là khẩu vị cá nhân của mình, mọi người tham khảo nhé.", "author": "shewriteshermind_", "post_id": "C4P5EqgvHd1", "created_at": "2024-07-12T08:08:56.700282+00:00", "external_id": "comment:shewriteshermind_|96w|-i-v-i-kh-u-v-c-nh-n-c-a-m-nh-th-n-kh-nh-t-v-kh-ng-c-i-m-n-o-qu-c", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "96w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-2", "text": "@linhmeo_93", "author": "_sunnny.893", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-31T08:08:56.700282+00:00", "external_id": "comment:_sunnny.893|102w|-linhmeo_93", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "102w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-3", "text": "@khanh___huy ăn huii", "author": "heidi.0506", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-24T08:08:56.700282+00:00", "external_id": "comment:heidi.0506|103w|-khanh___huy-n-huii", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "103w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-4", "text": "quá này ngon thật, trước mình có ghé vô ăn, mùi vị mặc dù mang phong cách đài loan nhưng lại khá hợp với mìn", "author": "hgh_1305", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-24T08:08:56.700282+00:00", "external_id": "comment:hgh_1305|103w|qu-n-y-ngon-th-t-tr-c-m-nh-c-gh-v-n-m-i-v-m-c-d-mang-phong-c-ch-i-lo", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "103w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-5", "text": "Địa chỉ quán ở đâu zạ mg?", "author": "vttngan", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-24T08:08:56.700282+00:00", "external_id": "comment:vttngan|103w|-a-ch-qu-n-u-z-mg-", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "103w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-6", "text": "@hoangflinh_", "author": "hacwsquare", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-24T08:08:56.700282+00:00", "external_id": "comment:hacwsquare|103w|-hoangflinh_", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "103w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-7", "text": "babiii @youngbb98", "author": "muplovesick", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-17T08:08:56.700282+00:00", "external_id": "comment:muplovesick|104w|babiii-youngbb98", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "104w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-8", "text": "@s.p.r.i.n.g.g", "author": "r.u.b.y_t.r.a.n", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-10T08:08:56.700282+00:00", "external_id": "comment:r.u.b.y_t.r.a.n|105w|-s.p.r.i.n.g.g", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "105w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-9", "text": "@_khucthu53_ @_nhhoanganhh", "author": "_thy.lynhh", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-10T08:08:56.700282+00:00", "external_id": "comment:_thy.lynhh|105w|-_khucthu53_-_nhhoanganhh", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "105w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-10", "text": "@dungdochan", "author": "mshanggg", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-10T08:08:56.700282+00:00", "external_id": "comment:mshanggg|105w|-dungdochan", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "105w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-11", "text": "Ăn ngon nha mấy ní", "author": "quockhanhle_", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-10T08:08:56.700282+00:00", "external_id": "comment:quockhanhle_|105w|-n-ngon-nha-m-y-n-", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "105w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-12", "text": "@ngvuonggg.tg1107 di an cai nay di anh", "author": "giaaahan", "post_id": "C4P5EqgvHd1", "created_at": "2024-05-10T08:08:56.700282+00:00", "external_id": "comment:giaaahan|105w|-ngvuonggg.tg1107-di-an-cai-nay-di-anh", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "105w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-13", "text": "Có bán trên app ko add ơi", "author": "chi4_chitu", "post_id": "C4P5EqgvHd1", "created_at": "2024-04-26T08:08:56.700282+00:00", "external_id": "comment:chi4_chitu|107w|c-b-n-tr-n-app-ko-add-i", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "107w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-14", "text": "địa chỉ ở đâu bạn ?", "author": "be.e.h.on.o.r", "post_id": "C4P5EqgvHd1", "created_at": "2024-04-26T08:08:56.700282+00:00", "external_id": "comment:be.e.h.on.o.r|107w|-a-ch-u-b-n-", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "107w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/C4P5EqgvHd1/#comment-15", "text": "台灣很有人氣的牛肉麵店一碗差不多台幣150,如果這間胡志明的牛肉麵一碗賣台幣115塊，我覺得很有勇氣 12.3K", "author": "aaaaaappp2003", "post_id": "C4P5EqgvHd1", "created_at": "2024-04-26T08:08:56.700282+00:00", "external_id": "comment:aaaaaappp2003|107w|-150-115-12.3k", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "107w", "parent_comment_id": ""}], "platform": "instagram", "post_url": "https://www.instagram.com/p/C4P5EqgvHd1/", "page_name": "FOOD BLOGGER IN SAIGON 🍱", "post_text": "6,206 likes, 66 comments - tebefood on March 8, 2024: &quot;#tebequan3 PHÁT HIỆN MỘT QUÁN MÌ BÒ HẦM NÚP HẺM CÔNG THỨC CHÁNH GỐC ĐÀI LOAN NGON ĐỈNH\n➖➖➖\n📍A Bowl Of Noodle\n🏡🏡 39 Nguyễn Sơn Hà, Quận 3\n⏰⏰ 11h-20h30\n💰💰38k-88k\n🌟🌟4.0/5.0\n➖➖➖\n📌 Về món:\n🍜🍲 Một quán Mì bò hầm tâm huyết của một chị chủ người Đài và công thức nguyên bản truyền thống từ Đài Loan luôn. Ăn thử thì phải công nhận mì ở đây rất ngon, nhân viên đem món ra là ta nói mùi thơm nức mũi, vừa đặt xuống là phải ăn liền. Sợi mì có 2 loại là dẹt và tròn, đều được làm thủ công, còn có củ cải ngâm chua ngọt ăn cùng mì kích thích vị giác lắm.\n\n🥜🥘 Tui thích nhất món Mì bò Đài Loan (88k) nước dùng rất thơm và đậm đà, phải ăn cùng với cải chua, làm tăng thêm hương vị của món ăn. Topping có trứng lòng đào &amp; 1 miếng bò bắp hoa siêu to và dày thịt mà lại mềm, chấm cùng với tương giấm pha thêm chút sa tế ăn tê tê đầu lưỡi. Mì gà chiên (72k) có phần gà chiên ăn cùng với mì, nhưng ăn đúng thì sẽ là ăn mì + húp nước xong rồi cắn thêm miếng gà chứ hong có bỏ gà vô mì đâu nhen. Nước dùng tô này tui ăn thấy thanh hơn, gà chiên có phủ lớp bột mỏng ngoài giòn nhưng bên trong lại cực kì mọng nước. Rcm mọi người thử Mì 2 loại xốt (68k) mix giữa sốt mè và sốt thịt bằm, trộn lên ăn cực kì béo luôn, topping thêm rau, trứng chiên và rất nhiều thịt bằm, tui ăn thấy khá là béo và dậy vị.\n\n🍳🥓 Ăn lai rai tui có gọi thêm phần Nấm chiên (42k) lớp bột bên ngoài giòn, bên trong nấm tươi ăn dai giòn sần sật. Gọi thêm Đậu hủ trứng bách thảo (38k) ăn cũng cực kì béo. Uống thêm nước sâm với trà chanh Quảng Đông uống thanh mát dữ luôn. \n➖➖➖➖\n📌 Về quán:\n🀄🎋 Không gian quán có nhiều chỗ ngồi, được decor theo style Trung Hoa nên rất là ấm cúng. Chị chủ người Đài với các bạn nhân viên rất là dễ thương. Chị cũng chia sẻ là chị rất tâm huyết với quán Mì bò hầm này, trước chị cũng đã mở quán ở Đài Loan rồi, nay mở rộng thêm chi nhánh ở Sài Gòn để mọi người có thể thưởng thức được hương vị thơm ngon nguyên bản của món ăn này nữa. Ai chưa thử có thể đến đây nha, nó ngon mà lần sau tui nhất định sẽ ghé đây ăn tiếp\n➖➖➖\n#tebefood #food #foodie #foodies #foods #foodporn #foodphotography #foody #foodyvn #diadiemanuong #instagood #instafood #likesforlike #follow #follow4followback #taiwan #quan3&quot;.", "source_file": "data/instagram/raw/meili_mi_bo_dai_loan/instagram_all_posts.json", "fnb_relevance": {"branch_hits": [], "negative_hits": [], "positive_hits": ["mì bò", "đài loan", "sủi cảo", "món ăn", "ăn", "food", "đánh giá", "chi nhánh", "địa chỉ"], "is_relevant_fnb": true, "relevance_score": 12, "generic_brand_hits": [], "explicit_brand_hits": ["mì bò đài loan"]}, "post_created_at": "2026-05-15T08:08:56.700282+00:00", "post_keyword_match": true, "parent_keyword_match": true, "post_keyword_matches": ["Mì Bò Đài Loan"]}', '6,206 likes, 66 comments - tebefood on March 8, 2024: &quot;#tebequan3 PHÁT HIỆN MỘT QUÁN MÌ BÒ HẦM NÚP HẺM CÔNG THỨC CHÁNH GỐC ĐÀI LOAN NGON ĐỈNH
