INSERT INTO meili_dashboard.raw_documents VALUES ('e9ffe6ec-07a7-438a-ae69-2c0df970a309', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'instagram', 'mention_post', 'instagram:post:DSuOnJykYGT', 'https://www.instagram.com/p/DSuOnJykYGT/', '2026-05-15 15:09:21.736671+07', '{"stats": {"like_count": null, "comment_count": 0}, "source": "instagram_keyword_filter_job", "page_id": "", "post_id": "DSuOnJykYGT", "comments": [{"url": "https://www.instagram.com/p/DSuOnJykYGT/#comment-1", "text": "Có tầng 3 nhé bạn", "author": "_handun", "post_id": "DSuOnJykYGT", "created_at": "2026-01-02T08:09:21.736671+00:00", "external_id": "comment:_handun|19w|c-t-ng-3-nh-b-n", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "19w", "parent_comment_id": ""}], "platform": "instagram", "post_url": "https://www.instagram.com/p/DSuOnJykYGT/", "page_name": "hoa 🦦", "post_text": "by.hoangnx on December 26, 2025: &quot;[HOÀN KIẾM] mì bò, mì thập cẩm\n📍Mì bò Đài Loan - 49 Trần Quốc Toản, Trần Hưng Đạo, Hoàn Kiếm, Hà Nội\n⏰ 10:30am - 21:00pm \n💵 60,000đ - 75,000đ/ bát \n\nQuán mì bò siêu hot vì ngon giờ mới được ăng đây\nTầng 1 là khu chế biến và thanh toán, tầng 2 là khu vực ăn, chủ yếu là bàn to ngồi 3 4 người nên đi 2 vào giờ trưa khả năng sẽ p ghép bàn vì quán đông\nKhẩu phần 1 bát mì bò rất là to, nhiều và đầy đặn. 1 bát thập cẩm 60k có bò, sườn, gân, xá xíu. \nNước dùng ở đây ngọt thanh, sợi mì k bị sượng, thịt bò mềm và ngọt vô cùng, sườn bò cũng được tẩm ướp gia vị ngọt, cũng mềm tan. Gân ko ăn nên k biết là loại giòn hay ninh mềm, xá xíu thái lát mỏng cũng mềm ko bị khô.&quot;.", "source_file": "data/instagram/raw/meili_mi_bo_dai_loan/instagram_all_posts.json", "fnb_relevance": {"branch_hits": [], "negative_hits": [], "positive_hits": ["mì bò", "đài loan", "ăn"], "is_relevant_fnb": true, "relevance_score": 10, "generic_brand_hits": [], "explicit_brand_hits": ["mì bò đài loan"]}, "post_created_at": "2026-05-15T08:09:21.736671+00:00", "post_keyword_match": true, "parent_keyword_match": true, "post_keyword_matches": ["Mì Bò Đài Loan"]}', 'by.hoangnx on December 26, 2025: &quot;[HOÀN KIẾM] mì bò, mì thập cẩm
