INSERT INTO meili_dashboard.raw_documents VALUES ('0b174663-7ef8-40d9-a872-e6205ca50434', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'facebook', 'mention_post', 'facebook:post:pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl', 'https://www.facebook.com/nhami5c/posts/pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl', '2026-05-19 23:44:57.278349+07', '{"source": "facebook_keyword_filter_job", "page_id": "search", "post_id": "pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl", "comments": [{"url": "https://www.facebook.com/nhami5c/posts/pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl?comment_id=pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_1", "text": "Mình ăn 4-5 lần rồi. Cơ bản là ngon, nhưng mà: Nước dùng hơi nồng (mùi tép hay sao đó). Có mấy hôm các bạn trụng cải hơi nhũn quá và rang cơm buổi sáng hơi bết. Còn lại ok hết nha", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.211335+00:00", "external_id": "comment:pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_1", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl?comment_id=pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_2", "text": "Có síp không bà Li ơi", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.211337+00:00", "external_id": "comment:pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_2", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl?comment_id=pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_3", "text": "Vô tình lướt thấy, hôm nay có ghé ăn với vợ, quán khá ngon, mà bộ quán thiếu kinh phí hay sao mà thuê có mỗi 1 bạn nhân viên vậy, thấy bạn chạy ra chạy vào mấy bàn rồi shipper hơi tội, món cũng làm khá nhanh mình vào chờ tầm 5 6p là có, quán thuê thêm 1 bạn nữa đi nhé, mì thập cẩm sủi cảo ngon lắm nha sốp sẽ quay lại ủng hộ", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.211338+00:00", "external_id": "comment:pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_3", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl?comment_id=pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_4", "text": "Làm lâu, quên món, phục vụ tệ.", "author": "Meili Mì Bò Đài Loan", "page_id": "search", "post_id": "pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl", "page_name": "Meili Mì Bò Đài Loan", "created_at": "2026-05-19T20:01:05.211340+00:00", "external_id": "comment:pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl_4", "record_type": "comment", "keyword_match": false, "keyword_matches": [], "parent_comment_id": "", "parent_keyword_match": true}, {"url": "https://www.facebook.com/nhami5c/posts/pfbid0UvUvzR28TGifkSvUCGLHHPBAzxxPXDYtG4Pq6Q1XVHL39kW58zsju5pa9nbJ6c9Nl?comment_id=pfbid0UvUvzR28TGifkSvUCGLHHPBAz