INSERT INTO meili_dashboard.raw_documents VALUES ('807c3cb5-0dcf-4268-9b3b-d3c2d074e2aa', NULL, '1bc4c68c-48f7-4b39-8064-e75d77ba6764', NULL, 'social', 'instagram', 'mention_post', 'instagram:post:DGAc7b6vAsJ', 'https://www.instagram.com/p/DGAc7b6vAsJ/', '2026-05-15 15:19:22.710326+07', '{"stats": {"like_count": null, "comment_count": 0}, "source": "instagram_keyword_filter_job", "page_id": "", "post_id": "DGAc7b6vAsJ", "comments": [{"url": "https://www.instagram.com/p/DGAc7b6vAsJ/#comment-1", "text": "có ship k ạ", "author": "khanhlyanngon", "post_id": "DGAc7b6vAsJ", "created_at": "2025-02-14T08:19:22.710326+00:00", "external_id": "comment:khanhlyanngon|65w|c-ship-k-", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "65w", "parent_comment_id": ""}, {"url": "https://www.instagram.com/p/DGAc7b6vAsJ/#comment-2", "text": "Ghé qua tường nhà mình chơi ha", "author": "khach.saigon", "post_id": "DGAc7b6vAsJ", "created_at": "2025-02-14T08:19:22.710326+00:00", "external_id": "comment:khach.saigon|65w|gh-qua-t-ng-nh-m-nh-ch-i-ha", "record_type": "comment", "crawl_source": "body_text", "keyword_match": false, "keyword_matches": [], "created_at_label": "65w", "parent_comment_id": ""}], "platform": "instagram", "post_url": "https://www.instagram.com/p/DGAc7b6vAsJ/", "page_name": "Công Vũ | Hà Nội Ăn Gì?", "post_text": "chubehanoi on February 13, 2025: &quot;🌿\nMÌ BÒ SƯỜN HẦM ĐÀI LOAN CỰC NGON Ở TRIỀU KHÚC mở đến 11h đêm\nNgon cực luôn. Giá 29-55K thôi nha, có mì rau củ hầm, mì trứng hầm và best-seller của quán này là mì bò hầm Đài Loan. Thịt bò miếng to ăn đẫm và cực kỳ mềm, mềm lắm luôn ấy, nhừ luôn. Thịt bò thơm, có chút mỡ mềm ngậy.\nSườn hầm cũng ngon và mềm rồi cả xá xíu nhá. Tuỳ mn chọn. Mình cứ chén tô đặc biệt đầy đủ quá nhiều thịt luôn.\nNước dùng ngọt nhẹ, đậm đà và thơm mùi gia vị hầm đặc trưng nhưng không gắt. Vừa vặn lắm. Kiểu mì trứng sợi to mềm mướt và ngoài mì có cả cơm nha.\nQuán đang có chương trình Tặng trà sâm dứa khi gọi 2 bát mì trở lên\nQuán 2 tầng rộng rãi. Có chỗ để xe.\n-Địa chỉ: Mì Bò Đài Loan - 41 Triều Khúc, Thanh Xuân (10h-23h)\n-ĐT: 0866.395.138\n#photography #photographer #hanoi #hanoifood #foodporn #foodie #omnomnom #streetstyle #streetfood #vietnamesefood #instadaily #instagood #likeforlikes #likeforlikes #likeforfollow #followme #foody #foodyhanoi #eatfamous #traditionalfood #noodles #beefnoodles&quot;.", "source_file": "data/instagram/raw/meili_mi_bo_dai_loan/instagram_all_posts.json", "fnb_relevance": {"branch_hits": [], "negative_hits": [], "positive_hits": ["mì bò", "đài loan", "ăn", "food", "địa chỉ", "ship"], "is_relevant_fnb": true, "relevance_score": 12, "generic_brand_hits": [], "explicit_brand_hits": ["mì bò đài loan"]}, "post_created_at": "2026-05-15T08:19:22.710326+00:00", "post_keyword_match": true, "parent_keyword_match": true, "post_keyword_matches": ["Mì Bò Đài Loan"]}', 'chubehanoi on February 13, 2025: &quot;🌿
